import { useCallback, useEffect, useRef, useState, type FormEvent, type ReactNode } from "react";
import { api, casePath, displayValue, errorText, intentApi, intentUpload, parseValue, statusLabel, type NumericLocale } from "./api";
import type { Case, Source } from "./types";
import type { ActualRow, CompanyProfile, Extraction, Fact, FundingRound, Preview, Question, Report, Scenario, Shareholder, WorkshopPage } from "./workshopTypes";
import { Button, Empty, Modal, PageNavigation } from "./ui";
import BridgeForm from "./BridgeForm";
import { companyProfileForForm, editCompanyProfile } from "./companyProfile";

type Props = { case: Case; page: WorkshopPage; refresh: number; sources: Source[]; blocked?: boolean; onRefresh: () => Promise<void>; onSource: () => void; onDraft: () => void; onCase: (id: string) => void; onSheet: (sheet: string, cell?: string) => void };
type Mutation = <T>(path: string, body?: Record<string, unknown>, method?: string) => Promise<T>;
type Shared = Props & { mutate: Mutation; busy: boolean };

function useData<T>(caseId: string, path: string, refresh: number) {
  const [data, setData] = useState<T | null>(null), [error, setError] = useState("");
  const [attempt, setAttempt] = useState(0);
  useEffect(() => {
    const controller = new AbortController();
    setError("");
    void api<T>(casePath(caseId) + path, "GET", undefined, controller.signal).then(setData).catch(e => { if (!controller.signal.aborted) setError(errorText(e)); });
    return () => controller.abort();
  }, [caseId, path, refresh, attempt]);
  return { data, error, retry: () => setAttempt(n => n + 1) };
}
function Card({ title, description, children }: { title: string; description?: string; children: ReactNode }) {
  return <section className="workshop-card"><div className="workshop-card-heading"><h2>{title}</h2>{description && <p>{description}</p>}</div>{children}</section>;
}
function FetchError({ message, retry }: { message: string; retry: () => void }) { return message ? <div className="inline-error" role="alert">{message}<Button onClick={retry}>Réessayer</Button></div> : null; }
function valueText(value: unknown): string {
  if (value == null) return "À compléter";
  if (typeof value === "number") return new Intl.NumberFormat("fr-FR", { maximumFractionDigits: 4 }).format(value);
  if (typeof value === "object") return Object.entries(value).map(([key, item]) => `${key} : ${valueText(item)}`).join(" · ");
  return displayValue(value);
}
function Diagnostics({ value }: { value: unknown }) {
  if (!value) return null;
  const items = Array.isArray(value) ? value : typeof value === "object" ? Object.entries(value).map(([key, entry]) => ({ label: key, value: entry })) : [value];
  if (!items.length) return null;
  return <details className="details-block"><summary>Points à vérifier</summary><ul>{items.map((item, index) => <li key={index}>{valueText(item)}</li>)}</ul></details>;
}
function MetricTable({ metrics }: { metrics?: Record<string, unknown> | unknown[] }) {
  if (!metrics || !Object.keys(metrics).length) return <p className="note">Les indicateurs apparaissent après calcul du classeur.</p>;
  const labels: Record<string, string> = { revenue: "Chiffre d’affaires", net_income: "Résultat net", cash_min: "Point bas de trésorerie", cash: "Trésorerie", cash_break_date: "Rupture de trésorerie", financing_need: "Besoin de financement", valuation: "Valorisation", ebitda: "EBE / EBITDA", pre_money: "Valorisation avant investissement", post_money: "Valorisation après investissement", investment: "Apport", pool_percent: "Pool salarié", total_shares: "Titres pleinement dilués" };
  const entries = Array.isArray(metrics) ? metrics.map((item, index) => [String((item as { id?: string })?.id || index), item] as const) : Object.entries(metrics);
  return <dl className="metric-list">{entries.map(([key, value]) => {
    const field = value && typeof value === "object" && Object.prototype.hasOwnProperty.call(value, "value") ? value as { label?: string; value?: unknown; status?: string; unit?: string } : null;
    return <div key={key}><dt>{field?.label || labels[key] || key.replaceAll("_", " ")}</dt><dd>{key === "cash_break_date" && field?.status === "CALCULE" && field.value === null ? "Aucune sur la période" : valueText(field ? field.value : value)}{field?.value != null && field.unit ? " " + field.unit : ""}</dd>{field?.status && <span className="note">{statusLabel(field.status)}</span>}</div>;
  })}</dl>;
}
function MonthlyScenarioComparison({ scenarios }: { scenarios: Scenario[] }) {
  const [metric, setMetric] = useState("cash");
  const available = [...new Map(scenarios.flatMap(scenario => scenario.series || []).map(series => [series.id, series])).values()];
  const selected = available.find(series => series.id === metric) || available[0];
  if (!selected) return null;
  const periods = [...new Set(scenarios.flatMap(scenario => scenario.series?.find(series => series.id === selected.id)?.categories || []))].sort();
  return <Card title="Comparaison mensuelle des scénarios" description="Les séries calculées sont alignées par mois. Une donnée manquante reste à compléter ; un mois extérieur au calendrier d’un scénario est marqué hors période."><label>Série mensuelle à comparer<select aria-label="Série mensuelle à comparer" value={selected.id} onChange={e => setMetric(e.target.value)}>{available.map(series => <option key={series.id} value={series.id}>{series.label || series.id}</option>)}</select></label><div className="draft-table-wrap"><table className="plain-table" aria-label={"Comparaison mensuelle : " + (selected.label || selected.id)}><thead><tr><th>Mois {selected.unit === "EUR" ? "· montants en €" : selected.unit ? "· " + selected.unit : ""}</th>{scenarios.map(scenario => <th key={scenario.id}>{scenario.name}</th>)}</tr></thead><tbody>{periods.map(period => <tr key={period}><th scope="row">{period}</th>{scenarios.map(scenario => { const series = scenario.series?.find(item => item.id === selected.id), index = series?.categories.indexOf(period) ?? -1; return <td key={scenario.id}>{!series ? "À compléter" : index < 0 ? "Hors période" : valueText(series.values[index])}</td>; })}</tr>)}</tbody></table></div></Card>;
}

function CapitalResult({ result }: { result: Record<string, unknown> }) {
  type Holder = { name: string; shares: string; percent: string };
  type Table = { holders?: Holder[]; pool_ownership?: string; pool_shares?: string };
  type Round = { name: string; pre_money?: string; post_money?: string; investment?: string; pool_target?: string; pool_timing?: string; warnings?: string[]; after?: Table };
  const initial = result.initial as Table | undefined, final = result.final as Table | undefined, rounds = (result.rounds || []) as Round[];
  const shown = (value: string | undefined) => value == null ? "—" : valueText(Number(value));
  return <><div className="draft-table-wrap"><table className="plain-table" aria-label="Répartition du capital pleinement dilué"><thead><tr><th>Associé / pool</th><th>Avant les tours</th>{rounds.map((round, index) => <th key={index}>{round.name}</th>)}<th>Titres finaux</th></tr></thead><tbody>{((result.holders || final?.holders || []) as Holder[]).map(holder => <tr key={holder.name}><td>{holder.name}</td><td>{shown(initial?.holders?.find(h => h.name === holder.name)?.percent)} %</td>{rounds.map((round, index) => <td key={index}>{shown(round.after?.holders?.find(h => h.name === holder.name)?.percent)} %</td>)}<td>{shown(holder.shares)}</td></tr>)}<tr><td>Pool salarié réservé</td><td>{initial?.pool_ownership == null ? "—" : valueText(Number(initial.pool_ownership) * 100)} %</td>{rounds.map((round, index) => <td key={index}>{round.after?.pool_ownership == null ? "—" : valueText(Number(round.after.pool_ownership) * 100)} %</td>)}<td>{shown(final?.pool_shares)}</td></tr></tbody></table></div>{rounds.map((round, index) => <div key={index}><h3>{round.name}</h3><MetricTable metrics={{ pre_money: Number(round.pre_money), investment: Number(round.investment), post_money: Number(round.post_money) }}/>{round.pool_target != null && <p className="note">Pool cible après le tour : {valueText(Number(round.pool_target) * 100)} % · constitution {round.pool_timing === "after" ? "après" : "avant"} le tour.</p>}{!!round.warnings?.length && <div className="inline-error" role="alert">{round.warnings.map((warning, n) => <p key={n}>{warning === "POOL_EXISTANT_SUPERIEUR_A_LA_CIBLE_AUCUNE_ANNULATION" ? "Le pool existant reste supérieur à la cible demandée : aucun titre réservé n’a été annulé. Le pourcentage conservé figure dans le tableau." : warning.replaceAll("_", " ")}</p>)}</div>}</div>)}<p className="note">Les titres fractionnaires expriment la simulation économique. Le pool correspond aux titres réservés non attribués.</p></>;
}
function Review({ preview, title, busy, close, apply }: { preview: Preview; title: string; busy: boolean; close: () => void; apply: () => void }) {
  const [page, setPage] = useState(0);
  const offset = Math.min(page, Math.max(0, Math.ceil((preview.changes?.length || 0) / 200) - 1)) * 200;
  return <Modal title={title} wide onClose={close}><p className="muted">Vérifiez ce lot avant de l’adopter. Cette validation porte uniquement sur les données présentées ici.</p>{preview.result && (preview.result.holders ? <CapitalResult result={preview.result}/> : <MetricTable metrics={preview.result}/>)}<PageNavigation count={preview.changes?.length || 0} page={page} onPage={setPage} label="éléments à adopter"/><div className="draft-table-wrap"><table className="plain-table"><thead><tr><th>Élément</th><th>Avant</th><th>Après</th></tr></thead><tbody>{(preview.changes || []).slice(offset, offset + 200).map((change, index) => <tr key={index}><td>{valueText(change.label || change.metric || change.field_id || change.name || change.period || index + 1)}</td><td>{valueText(change.before ?? change.old)}</td><td>{valueText(change.after ?? change.new ?? change.value)}</td></tr>)}</tbody></table></div><Diagnostics value={preview.diagnostics}/><div className="modal-footer"><Button onClick={close}>Fermer l’aperçu</Button><Button className="primary" disabled={busy || !preview.approval_token} onClick={apply}>Approuver et adopter</Button></div></Modal>;
}

export default function Workshop(props: Props) {
  const [error, setError] = useState(""), [notice, setNotice] = useState(""), [busy, setBusy] = useState(false), [localRefresh, setLocalRefresh] = useState(0);
  const selected = useRef(props.case.id); selected.current = props.case.id;
  const mutate: Mutation = useCallback(async <T,>(path: string, body: Record<string, unknown> = {}, method = "POST") => {
    const id = props.case.id; setBusy(true); setError(""); setNotice("");
    try {
      const result = await intentApi<T>(id, path, method, { expected_revision: props.case.revision ?? 0, ...body });
      if (selected.current === id) { setNotice("Demande enregistrée dans ce dossier."); setLocalRefresh(n => n + 1); await props.onRefresh(); }
      return result;
    } catch (e) { if (selected.current === id) setError(errorText(e)); throw e; }
    finally { if (selected.current === id) setBusy(false); }
  }, [props.case.id, props.case.revision, props.onRefresh]);
  const shared = { ...props, refresh: props.refresh + localRefresh, mutate, busy: busy || !!props.blocked };
  return <div className="workshop-page" aria-label="Parcours du dossier">{error && <div className="inline-error" role="alert">{error}</div>}{notice && <div className="inline-notice" role="status">{notice}</div>}
    {props.page === "company" && <Company {...shared}/>}
    {props.page === "documents" && <Documents {...shared}/>}
    {props.page === "forecast" && <><Qualifications {...shared}/><Questionnaire {...shared}/><Records {...shared}/></>}
    {props.page === "scenarios" && <Scenarios {...shared}/>}
    {props.page === "actuals" && <Actuals {...shared}/>}
    {props.page === "reports" && <Reports {...shared}/>}
  </div>;
}

function Company(p: Shared) {
  const remote = useData<{ profile: CompanyProfile }>(p.case.id, "/profile", p.refresh);
  const [profile, setProfile] = useState<CompanyProfile | null>(null), dirty = useRef(false), editVersion = useRef(0);
  useEffect(() => { if (remote.data && !dirty.current) setProfile(companyProfileForForm(remote.data.profile)); }, [remote.data]);
  function field(key: keyof CompanyProfile, value: unknown) { dirty.current = true; editVersion.current += 1; setProfile(current => current && editCompanyProfile(current, key, value)); }
  async function save(e: FormEvent) {
    e.preventDefault();
    if (!profile || p.busy) return;
    const submittedVersion = editVersion.current;
    try {
      const saved = await p.mutate<{ profile: CompanyProfile }>("/profile", { profile: companyProfileForForm(profile) }, "PUT");
      // Acknowledging the submitted snapshot must not acknowledge or replace
      // a newer edit made while the save and its refresh were in flight.
      if (editVersion.current === submittedVersion) {
        dirty.current = false;
        setProfile(companyProfileForForm(saved.profile));
      }
    } catch { /* Error shown by the workspace; unsaved edits are retained. */ }
  }
  const modules = [{ id: "sales", label: "Ventes" }, { id: "staff", label: "Recrutements" }, { id: "investments", label: "Investissements" }, { id: "debt", label: "Emprunts" }, { id: "grants", label: "Subventions" }, { id: "equity", label: "Levée de fonds" }];
  if (!profile) return <><FetchError message={remote.error} retry={remote.retry}/><Card title="Votre entreprise"><p>Chargement du profil enregistré…</p></Card></>;
  return <><FetchError message={remote.error} retry={remote.retry}/><Card title="Votre entreprise" description="Ces informations adaptent le parcours. Les hypothèses du classeur restent soumises à votre validation."><form className="form-stack" onSubmit={save}><div className="form-grid"><label>Nom de l’entreprise<input value={profile.name || ""} onChange={e => field("name", e.target.value)} placeholder={p.case.client_name}/></label><label>Activité<select aria-label="Activité" value={profile.activity || ""} onChange={e => field("activity", e.target.value)}><option value="">À préciser</option><option value="services">Services</option><option value="recurring">Services récurrents / abonnements</option><option value="trading">Négoce / commerce</option><option value="production">Production</option><option value="mixed">Activité mixte</option></select></label><label>Modèle de revenus<input value={profile.revenue_model || ""} onChange={e => field("revenue_model", e.target.value)} placeholder="Abonnements, projets, unités vendues…"/></label><label>Première année<input type="number" min={2000} max={2100} value={profile.start_year ?? new Date().getFullYear()} onChange={e => field("start_year", Number(e.target.value))}/></label><label>Horizon du prévisionnel<select aria-label="Horizon du prévisionnel" value={profile.horizon_years ?? 5} onChange={e => field("horizon_years", Number(e.target.value))}>{Array.from({ length: 10 }, (_, n) => <option key={n + 1} value={n + 1}>{n + 1} an{n ? "s" : ""}</option>)}</select></label><label>Démarrage de l’activité<input type="date" required min={`${profile.start_year}-01-01`} max={`${profile.start_year}-12-31`} value={profile.activity_start || ""} onChange={e => field("activity_start", e.target.value)}/></label></div><p className="note">Exercices de janvier à décembre. Le démarrage peut intervenir en cours d’année.</p><label>Décisions à préparer<textarea rows={3} value={profile.objectives || ""} onChange={e => field("objectives", e.target.value)} placeholder="Développement commercial, recrutement, nouveau site, financement…"/></label><fieldset className="module-options"><legend>Modules concernés</legend>{modules.map(module => <label key={module.id}><input type="checkbox" checked={(profile.modules || []).includes(module.id)} onChange={e => field("modules", e.target.checked ? [...(profile.modules || []), module.id] : (profile.modules || []).filter(id => id !== module.id))}/>{module.label}</label>)}</fieldset><div className="button-group"><Button className="primary" disabled={p.busy}>Enregistrer le profil</Button><Button type="button" disabled={p.busy || dirty.current || !remote.data} onClick={() => void p.mutate("/profile/propose", {}).then(() => p.onDraft()).catch(() => {})}>Proposer ce calendrier au classeur</Button></div></form></Card><Qualifications {...p}/><Questionnaire {...p}/></>;
}

function questionKey(q: { field_id?: string; sheet?: string; cell?: string }) { return [q.field_id || "", q.sheet || "", q.cell || ""].join("|"); }
function numericQuestion(q: Question) { return !q.calculated && !/wacc/i.test(q.field_id + q.label) && (["number", "integer", "percent"].includes(q.value_type || "") || (!q.value_type && typeof q.value === "number")); }
function Qualifications(p: Shared) {
  const remote = useData<{ modules: { id: string; label: string }[]; declarations?: unknown; questions?: (string | { question?: string; message?: string; sheet?: string; cell?: string })[] }>(p.case.id, "/qualifications", p.refresh);
  const [module, setModule] = useState(""), [state, setState] = useState(""), [status, setStatus] = useState(""), [evidence, setEvidence] = useState(""), [reason, setReason] = useState(""), [jurisdiction, setJurisdiction] = useState(""), [from, setFrom] = useState(""), [to, setTo] = useState("");
  const [preview, setPreview] = useState<Preview | null>(null), fiscal = module === "REGLES_FISCALES";
  async function prepare(event: FormEvent) {
    event.preventDefault(); const declaration = { module, state: fiscal ? "ACTIF" : state, status, evidence, reason, ...(fiscal ? { jurisdiction, valid_from: from, valid_to: to } : {}) };
    try { const result = await p.mutate<Preview>("/qualifications/preview", { declaration }); setPreview({ ...result, result: { "Module": remote.data?.modules.find(item => item.id === module)?.label || module, "Périmètre": fiscal || state === "ACTIF" ? "Actif" : "Inactif", "Qualification": status === "CONFIRME" ? "Confirmée par la source" : "Hypothèse", "Source": p.sources.find(source => source.id === evidence)?.title, "Justification": reason, ...(fiscal ? { "Juridiction": jurisdiction, "Début de validité": from, "Fin de validité": to } : {}) } }); } catch { /* All declarations remain reviewable. */ }
  }
  return <Card title="Confirmer les modules et les règles du dossier" description="Indiquez ce qui s’applique à votre entreprise et documentez chaque qualification. Des chiffres renseignés ne suffisent pas à confirmer un module ou une règle fiscale."><FetchError message={remote.error} retry={remote.retry}/><form className="form-stack" onSubmit={prepare}><div className="form-grid"><label>Module à qualifier<select aria-label="Module à qualifier" required value={module} onChange={e => { setModule(e.target.value); setPreview(null); }}><option value="">Choisir un module</option>{remote.data?.modules?.map(item => <option key={item.id} value={item.id}>{item.label}</option>)}</select></label><label>Application du module<select aria-label="Application du module" required disabled={fiscal} value={fiscal ? "ACTIF" : state} onChange={e => { setState(e.target.value); setPreview(null); }}><option value="">Choisir le périmètre</option><option value="ACTIF">Actif dans ce dossier</option><option value="INACTIF">Inactif dans ce dossier</option></select></label><label>Qualification de la déclaration<select aria-label="Qualification de la déclaration" required value={status} onChange={e => { setStatus(e.target.value); setPreview(null); }}><option value="">Choisir la qualification</option><option value="CONFIRME">Confirmée par la source</option><option value="HYPOTHESE">Hypothèse à confirmer</option></select></label><label>Source de la qualification<select aria-label="Source de la qualification" required value={evidence} onChange={e => { setEvidence(e.target.value); setPreview(null); }}><option value="">Choisir une source</option>{p.sources.map(source => <option key={source.id} value={source.id}>{source.title}</option>)}</select></label>{fiscal && <><label>Juridiction fiscale<input required value={jurisdiction} placeholder="Juridiction applicable" onChange={e => { setJurisdiction(e.target.value); setPreview(null); }}/></label><label>Début de validité fiscale<input required type="date" value={from} onChange={e => { setFrom(e.target.value); setPreview(null); }}/></label><label>Fin de validité fiscale<input required type="date" min={from} value={to} onChange={e => { setTo(e.target.value); setPreview(null); }}/></label></>}</div><label>Justification de la qualification<textarea required rows={2} value={reason} onChange={e => { setReason(e.target.value); setPreview(null); }}/></label><div className="button-group"><Button type="button" onClick={p.onSource}>Ajouter une source</Button><Button disabled={p.busy || !module || !evidence || !status || (!fiscal && !state)}>Examiner cette qualification</Button></div></form><Diagnostics value={remote.data?.declarations}/>{!!remote.data?.questions?.length && <div className="record-questions"><h3>Informations encore nécessaires</h3><ul>{remote.data.questions.map((question, index) => <li key={index}>{typeof question === "string" ? question : question.question || question.message || valueText(question)}{typeof question !== "string" && question.sheet && <button className="text-button" onClick={() => p.onSheet(question.sheet!, question.cell)}>Ouvrir {question.sheet}{question.cell ? " · " + question.cell : ""}</button>}</li>)}</ul></div>}{preview && <Review title="Aperçu de la qualification" preview={preview} busy={p.busy} close={() => setPreview(null)} apply={() => void p.mutate("/qualifications/apply", { approval_token: preview.approval_token }).then(() => setPreview(null)).catch(() => {})}/>}</Card>;
}
function Questionnaire(p: Shared) {
  const remote = useData<{ questions: Question[]; progress?: Record<string, unknown> }>(p.case.id, "/questionnaire", p.refresh);
  const [filter, setFilter] = useState(""), [values, setValues] = useState<Record<string, string>>({}), [statuses, setStatuses] = useState<Record<string, string>>({}), [proofs, setProofs] = useState<Record<string, string>>({});
  const questions = remote.data?.questions || [];
  const shown = questions.filter(q => `${q.label || q.question} ${q.sheet}`.toLocaleLowerCase("fr").includes(filter.toLocaleLowerCase("fr")));
  async function send() {
    const answers = questions.filter(q => Object.prototype.hasOwnProperty.call(values, questionKey(q))).map(q => ({ field_id: q.field_id, sheet: q.sheet, cell: q.cell, value: parseValue(values[questionKey(q)]), status: statuses[questionKey(q)] || "HYPOTHESE", ...(proofs[questionKey(q)] ? { evidence_id: proofs[questionKey(q)] } : {}) }));
    try { await p.mutate("/answers", { answers }); setValues({}); p.onDraft(); } catch { /* Keep all answers on rejection. */ }
  }
  return <Card title="Construire les hypothèses" description="Renseignez les champs utiles ; les réponses alimentent le même brouillon que le tableur et le chat."><FetchError message={remote.error} retry={remote.retry}/>{remote.data?.progress && <MetricTable metrics={remote.data.progress}/>}<input aria-label="Filtrer les questions" placeholder="Rechercher une question ou une feuille" value={filter} onChange={e => setFilter(e.target.value)}/><div className="question-list">{shown.slice(0, 100).map(q => <div className="question-row" key={questionKey(q)}><div><label htmlFor={"q-" + questionKey(q)}>{q.label || q.question || q.field_id}{q.required && <span className="badge warning">Requis</span>}</label><button className="text-button" onClick={() => q.sheet && p.onSheet(q.sheet, q.cell)}>{q.sheet}{q.cell ? " · " + q.cell : ""}</button><span className="note">{statusLabel(q.status)}{q.unit ? " · " + q.unit : ""}</span>{q.explanation && <p className="note">{q.explanation}</p>}{q.field_id.includes("employee_end") && <p className="note">Le mois de sortie est exclu du coût dans cette trame. Une sortie au 31 décembre compte jusqu’à novembre.</p>}</div><input list={"choices-" + questionKey(q)} aria-label={q.label || q.question || q.field_id} id={"q-" + questionKey(q)} value={values[questionKey(q)] ?? displayValue(q.value)} onChange={e => setValues(current => ({ ...current, [questionKey(q)]: e.target.value }))} placeholder="À compléter"/><datalist id={"choices-" + questionKey(q)}>{(q.choices || q.options || []).map((choice, index) => <option key={index} value={typeof choice === "object" && choice !== null ? String((choice as { value?: unknown }).value ?? "") : String(choice)}/>)}</datalist><select aria-label={"État : " + (q.label || q.field_id)} value={statuses[questionKey(q)] || "HYPOTHESE"} onChange={e => { setStatuses(current => ({ ...current, [questionKey(q)]: e.target.value })); setValues(current => ({ ...current, [questionKey(q)]: current[questionKey(q)] ?? displayValue(q.value) })); }}><option value="HYPOTHESE">Hypothèse provisoire</option><option value="CONFIRME">Information confirmée</option></select><select aria-label={"Source : " + (q.label || q.field_id)} value={proofs[questionKey(q)] || ""} onChange={e => { setProofs(current => ({ ...current, [questionKey(q)]: e.target.value })); setValues(current => ({ ...current, [questionKey(q)]: current[questionKey(q)] ?? displayValue(q.value) })); }}><option value="">Réponse manuelle</option>{p.sources.map(source => <option key={source.id} value={source.id}>{source.title}</option>)}</select></div>)}</div>{shown.length > 100 && <p className="note">100 questions affichées. Filtrez pour accéder aux suivantes.</p>}{!questions.length && !remote.error && <p className="note">Les questions seront proposées à partir du profil et du catalogue du dossier.</p>}<Button className="primary" disabled={p.busy || !Object.keys(values).length} onClick={() => void send()}>Proposer les réponses au brouillon</Button></Card>;
}

function ExtractionWarnings({ warnings }: { warnings?: string[] }) {
  if (!warnings?.length) return null;
  const labels: Record<string, string> = {
    OCR_REQUIS_INDISPONIBLE: "OCR local indisponible : relancez Installer_TCA_BP_Web.ps1, puis relancez l’extraction.",
    OCR_DESACTIVE: "OCR désactivé : les pages scannées nécessitent une nouvelle extraction avec l’OCR local.",
    FORMULES_CACHEES_NON_RECALCULEES: "Le document contient des résultats de formules Excel en cache, dont le recalcul n’a pas été vérifié.",
    FORMULE_SANS_CACHE: "Une formule Excel ne possède pas de résultat enregistré ; sa valeur reste à compléter.",
    EXTRACTION_TRONQUEE_MAX_BLOCKS: "Extraction incomplète : limite de blocs atteinte. Importez un extrait plus court pour lire la suite.",
    EXTRACTION_TRONQUEE_MAX_FACTS: "Extraction incomplète : limite d’informations atteinte. Importez un extrait plus court pour lire la suite.",
    EXTRACTION_TRONQUEE_MAX_PAGES: "Extraction incomplète : limite de pages atteinte. Importez les pages restantes dans un autre document.",
    FORMATS_DATES_UNITES_EXCEL_A_CONFIRMER: "Confirmez les formats, dates et unités provenant d’Excel avant de retenir une valeur.",
    PAGINATION_DOCX_NON_DETERMINEE: "Les paragraphes et tableaux Word sont repérés ; les numéros de page ne sont pas déterminés.",
  };
  return <div className="inline-error" role="alert"><strong>Limites de cette extraction</strong><ul>{warnings.map((warning, index) => <li key={index}>{labels[warning] || (/^OCR_ECHEC_PAGE_\d+$/.test(warning) ? "Lecture OCR échouée pour la page " + warning.split("_").at(-1) + ". Vérifiez la lisibilité du scan puis relancez l’extraction." : warning.replaceAll("_", " "))}</li>)}</ul></div>;
}

function Documents(p: Shared) {
  const remote = useData<{ extractions: Extraction[] }>(p.case.id, "/extractions", p.refresh);
  const [selected, setSelected] = useState<Extraction | null>(null), [facts, setFacts] = useState<Fact[]>([]), [enabled, setEnabled] = useState<Set<number>>(new Set());
  const questions = useData<{ questions: Question[] }>(p.case.id, "/questionnaire", p.refresh);
  function readFacts(extraction: Extraction): Fact[] { return (extraction.facts || []).map((fact, index) => ({ ...fact, id: fact.id || String(index), value: fact.normalized_value != null ? parseValue(String(fact.normalized_value)) : fact.value, page: fact.page || fact.location?.page })); }
  async function inspect(extraction: Extraction) {
    setSelected(extraction); setFacts(readFacts(extraction)); setEnabled(new Set());
    try { const detail = await api<Extraction & { extraction?: Extraction }>(casePath(p.case.id) + "/extractions/" + encodeURIComponent(extraction.id)); const current = detail.extraction || detail; setSelected(current); setFacts(readFacts(current)); } catch { /* The list snapshot remains visible; diagnostics explain incomplete extraction. */ }
  }
  async function propose() { if (!selected) return; try { await p.mutate("/extractions/" + encodeURIComponent(selected.id) + "/propose", { facts: facts.filter((_, i) => enabled.has(i)) }); setSelected(null); p.onDraft(); } catch { /* Preview stays open. */ } }
  return <><Card title="Pièces et informations" description="Importez vos documents, puis contrôlez les informations extraites. L’OCR traite les scans sur ce poste."><Button icon="upload" onClick={p.onSource}>Importer un document ou une réponse</Button><FetchError message={remote.error} retry={remote.retry}/><div className="document-list">{p.sources.map(source => <article key={source.id}><div><h3>{source.title}</h3><p className="note">{source.kind || "Document"} · source du dossier</p></div><Button disabled={p.busy} onClick={() => void p.mutate("/extractions", { source_id: source.id }).catch(() => {})}>Extraire les informations</Button>{(remote.data?.extractions || []).filter(e => e.source_id === source.id).map(extraction => <Button key={extraction.id} onClick={() => void inspect(extraction)}>{statusLabel(extraction.status)} · Examiner les preuves</Button>)}</article>)}</div>{!p.sources.length && <Empty icon="file" title="Commencez par vos documents"><p>PDF, Word, Excel, CSV, texte et images scannées.</p></Empty>}</Card>{selected && <Modal title={"Informations extraites · " + (selected.title || p.sources.find(s => s.id === selected.source_id)?.title || "Document")} wide onClose={() => setSelected(null)}>{!!p.sources.find(source => source.id === selected.source_id)?.path && <a className="button" target="_blank" rel="noopener noreferrer" href={"/api" + casePath(p.case.id) + "/sources/" + encodeURIComponent(selected.source_id) + "/file"}>Ouvrir la pièce source</a>}<p className="note">Sélectionnez les faits à proposer et rattachez-les à un champ. Une extraction est une proposition à vérifier.</p><ExtractionWarnings warnings={selected.warnings}/><div className="fact-list">{facts.map((fact, index) => <article key={fact.id || index}><label className="checkbox-row"><input type="checkbox" checked={enabled.has(index)} onChange={e => setEnabled(current => { const next = new Set(current); e.target.checked ? next.add(index) : next.delete(index); return next; })}/>{fact.label || "Information " + (index + 1)}</label><blockquote>{fact.raw || fact.raw_value || fact.text || displayValue(fact.value)}</blockquote>{fact.cached_formula && <p className="inline-error">Valeur issue du cache d’une formule Excel, sans recalcul vérifié. Contrôlez sa fraîcheur dans la pièce source avant de la confirmer.</p>}<p className="note">{fact.page ? "Page " + fact.page : ""}{fact.location?.sheet ? " · " + fact.location.sheet : ""}{fact.location?.cell ? " · Cellule " + fact.location.cell : ""}{fact.confidence != null ? " · Confiance " + Math.round(fact.confidence <= 1 ? fact.confidence * 100 : fact.confidence) + " %" : ""}</p><div className="form-grid"><label>Valeur retenue<input value={displayValue(fact.value)} onChange={e => setFacts(current => current.map((f, n) => n === index ? { ...f, value: parseValue(e.target.value) } : f))}/></label><label>Champ destinataire<select value={fact.field_id ? questionKey(fact) : ""} onChange={e => setFacts(current => current.map((f, n) => n === index ? { ...f, field_id: questions.data?.questions?.find(q => questionKey(q) === e.target.value)?.field_id, sheet: questions.data?.questions?.find(q => questionKey(q) === e.target.value)?.sheet, cell: questions.data?.questions?.find(q => questionKey(q) === e.target.value)?.cell } : f))}><option value="">Choisir un champ</option>{questions.data?.questions?.map(q => <option value={questionKey(q)} key={questionKey(q)}>{q.label || q.field_id} · {q.sheet}</option>)}</select></label></div></article>)}</div><details className="details-block" open={!facts.length}><summary>Texte et pages du document</summary><div className="source-transcript">{selected.text || selected.pages?.map(page => `Page ${page.page || ""}\n${page.text || ""}`).join("\n\n") || "Le texte n’a pas été extrait. Consultez les diagnostics puis relancez si nécessaire."}</div></details><Diagnostics value={selected.diagnostics}/><div className="modal-footer"><Button onClick={() => setSelected(null)}>Fermer les informations</Button><Button className="primary" disabled={p.busy || !enabled.size || facts.some((f, i) => enabled.has(i) && !f.field_id)} onClick={() => void propose()}>Proposer les faits sélectionnés</Button></div></Modal>}</>;
}

function Records(p: Shared) {
  type Register = { sheet: string; label?: string; first_free_row?: number | null; can_extend?: boolean; questions?: { question?: string; message?: string }[]; fields: { field_id: string; label?: string; value_type?: string; required?: boolean; choices?: unknown[]; default?: unknown; calculated?: boolean }[] };
  const remote = useData<{ registers: Register[]; questions?: { question?: string; message?: string; sheet?: string }[] }>(p.case.id, "/registers", p.refresh);
  const [sheet, setSheet] = useState(""), [values, setValues] = useState<Record<string, string>>({}), [evidence, setEvidence] = useState(""), [questions, setQuestions] = useState<{ question?: string; message?: string }[]>([]), [count, setCount] = useState(1);
  const register = remote.data?.registers?.find(r => r.sheet === sheet) || remote.data?.registers?.[0];
  async function propose(event: FormEvent) {
    event.preventDefault(); if (!register) return;
    const fields = Object.fromEntries(register.fields.filter(field => values[field.field_id] !== undefined).map(field => [field.field_id, parseValue(values[field.field_id])]));
    try { const result = await p.mutate<{ questions?: { question?: string; message?: string }[]; status?: string; message?: string }>("/registers/" + encodeURIComponent(register.sheet) + "/records", { values: fields, evidence_id: evidence }); if (result.questions?.length || ["NEEDS_INPUT", "NEEDS_REVIEW", "REFUSED"].includes(result.status || "")) { setQuestions(result.questions?.length ? result.questions : [{ question: result.message || "Informations à compléter." }]); return; } setQuestions([]); setValues({}); p.onDraft(); } catch { /* Fields stay available while business questions are resolved. */ }
  }
  const pending = [...questions, ...(register?.questions || []), ...(remote.data?.questions || []).filter(q => !q.sheet || q.sheet === register?.sheet)].filter((question, index, all) => all.findIndex(other => (other.question || other.message) === (question.question || question.message)) === index);
  const clarification = !!pending.length && <div className="record-questions" role="status"><h3>Informations à compléter</h3><ul>{pending.map((q, index) => <li key={index}>{q.question || q.message}</li>)}</ul></div>;
  const extension = register?.can_extend && <div className="inline-form"><label>Lignes supplémentaires<input aria-label="Lignes métier supplémentaires" type="number" min={1} max={50} value={count} onChange={e => setCount(Number(e.target.value))}/></label><Button type="button" disabled={p.busy || count < 1 || count > 50 || !Number.isInteger(count)} onClick={() => void p.mutate("/registers/" + encodeURIComponent(register.sheet) + "/extend", { count }).then(() => p.onDraft()).catch(() => {})}>Préparer l’extension du registre</Button></div>;
  return <Card title="Ajouter une opération métier" description="Décrivez un contrat, un recrutement, un investissement ou un financement. L’agent du registre contrôle les informations et prépare le brouillon."><FetchError message={remote.error} retry={remote.retry}/>{register ? <form className="form-stack" onSubmit={propose}>{clarification}<label>Registre<select aria-label="Registre métier" value={register.sheet} onChange={e => { setSheet(e.target.value); setValues({}); setQuestions([]); }}>{remote.data?.registers?.map(r => <option key={r.sheet} value={r.sheet}>{r.label || r.sheet}</option>)}</select></label>{register.first_free_row === null && <p className="note">Ce registre est rempli. Son extension doit être préparée avant une nouvelle opération.</p>}<div className="form-grid">{register.fields.map(field => <label key={field.field_id}>{field.label || field.field_id}{field.field_id.includes("employee_end") && <span className="field-hint">Le mois de sortie est exclu du calcul.</span>}{field.calculated && <span className="field-hint">Défaut calculé conservé</span>}{field.required && <span className="field-hint">Information requise</span>}<input required={field.required} readOnly={field.calculated} list={"record-" + field.field_id} value={values[field.field_id] ?? displayValue(field.default)} onChange={e => setValues(current => ({ ...current, [field.field_id]: e.target.value }))}/><datalist id={"record-" + field.field_id}>{(field.choices || []).map((choice, index) => <option key={index} value={typeof choice === "object" && choice !== null ? String((choice as { value?: unknown }).value ?? "") : String(choice)}/>)}</datalist></label>)}</div><label>Source de cette opération<select aria-label="Source de cette opération" required value={evidence} onChange={e => setEvidence(e.target.value)}><option value="">Choisir une pièce ou une réponse</option>{p.sources.map(source => <option key={source.id} value={source.id}>{source.title}</option>)}</select></label><div className="button-group"><Button type="button" onClick={p.onSource}>Ajouter une source</Button><Button className="primary" disabled={p.busy || !evidence || register.first_free_row === null}>Préparer cette opération au brouillon</Button></div>{extension}</form> : !remote.error && <p className="note">Lecture des registres du modèle…</p>}</Card>;
}

function Scenarios(p: Shared) {
  const remote = useData<{ scenarios: Scenario[] }>(p.case.id, "/scenarios", p.refresh);
  const comparison = useData<{ scenarios?: Scenario[]; metrics?: Record<string, unknown>; calendars_identical?: boolean }>(p.case.id, "/scenarios/compare", p.refresh);
  const [name, setName] = useState(""), [offer, setOffer] = useState("");
  async function create(e: FormEvent) { e.preventDefault(); try { await p.mutate("/scenarios", { name }); setName(""); } catch { /* The scenario name remains available. */ } }
  return <><Card title="Scénarios de décision" description="Chaque scénario conserve sa révision de départ. Ouvrez sa copie pour modifier ses hypothèses, puis recalculez-la. Les scénarios, recherches d’objectif et sensibilités utilisent le prévisionnel. La prévision actualisée avec le réalisé se consulte séparément dans Réalisé."><FetchError message={remote.error} retry={remote.retry}/><form className="inline-form" onSubmit={create}><label>Nom du scénario<input required value={name} onChange={e => setName(e.target.value)} placeholder="Recrutement commercial en janvier"/></label><Button className="primary" disabled={p.busy || !name.trim()}>Créer une copie de scénario</Button></form><div className="document-list">{remote.data?.scenarios?.map(scenario => <article key={scenario.id}><div><h3>{scenario.name}</h3><p className="note">Révision de départ {scenario.base_revision ?? "—"} · {statusLabel(scenario.status)}</p></div><Button disabled={!scenario.case_id} onClick={() => scenario.case_id && p.onCase(scenario.case_id)}>Ouvrir le scénario</Button></article>)}</div><FetchError message={comparison.error} retry={comparison.retry}/>{comparison.data?.calendars_identical === false && <p className="inline-error">Les scénarios utilisent des calendriers différents. Comparez les années indiquées, pas leur position dans les tableaux.</p>}{comparison.data?.scenarios?.map(scenario => <details className="details-block" key={scenario.id}><summary>{scenario.name}</summary><MetricTable metrics={scenario.metrics}/>{scenario.annual_metrics && <><h3>Résultats par année</h3><MetricTable metrics={scenario.annual_metrics}/></>}</details>)}{comparison.data?.metrics && <MetricTable metrics={comparison.data.metrics}/>}</Card><MonthlyScenarioComparison scenarios={comparison.data?.scenarios || []}/><Card title="Étendre le catalogue" description="Une offre métier ajoute ses champs, formules et dépendances dans le brouillon de structure."><form className="inline-form" onSubmit={e => { e.preventDefault(); void p.mutate("/offers", { name: offer }).then(() => { setOffer(""); p.onDraft(); }).catch(() => {}); }}><label>Nom de la nouvelle offre<input required value={offer} onChange={e => setOffer(e.target.value)}/></label><Button disabled={p.busy || !offer.trim()}>Préparer une offre supplémentaire</Button></form></Card><Capitalization {...p}/><Goals {...p}/><Sensitivities {...p}/></>;
}

function Capitalization(p: Shared) {
  const remote = useData<{ shareholders: Shareholder[]; rounds: FundingRound[]; result?: Record<string, unknown> }>(p.case.id, "/capitalization", p.refresh);
  const [shareholders, setShareholders] = useState<Shareholder[]>([{ name: "", shares: 1000 }]), [rounds, setRounds] = useState<FundingRound[]>([]), [preview, setPreview] = useState<Preview | null>(null), dirty = useRef(false);
  useEffect(() => { if (remote.data && !dirty.current) { if (remote.data.shareholders?.length) setShareholders(remote.data.shareholders); setRounds(remote.data.rounds || []); } }, [remote.data]);
  const editHolder = (index: number, key: keyof Shareholder, value: string | number) => { dirty.current = true; setPreview(null); setShareholders(current => current.map((holder, n) => n === index ? { ...holder, [key]: value } : holder)); };
  const editRound = (index: number, key: keyof FundingRound, value: string | number) => { dirty.current = true; setPreview(null); setRounds(current => current.map((round, n) => n === index ? { ...round, [key]: value } : round)); };
  async function compute(e: FormEvent) { e.preventDefault(); try { const result = await p.mutate<Preview>("/capitalization", { shareholders, rounds }); setPreview(result); } catch { /* Keep current inputs. */ } }
  return <Card title="Capital et dilution" description="Simulez plusieurs tours en numéraire. Le pool salarié est inclus dans la base pleinement diluée ; son moment de constitution reste explicite."><FetchError message={remote.error} retry={remote.retry}/><form className="form-stack" onSubmit={compute}><h3>Associés avant les tours</h3>{shareholders.map((holder, index) => <div className="form-grid holder-row" key={index}><label>Associé {index + 1}<input required value={holder.name} onChange={e => editHolder(index, "name", e.target.value)}/></label><label>Titres détenus<input type="number" required min={0} step="any" value={holder.shares} onChange={e => editHolder(index, "shares", Number(e.target.value))}/></label><Button type="button" aria-label={"Supprimer l’associé " + (index + 1)} disabled={shareholders.length < 2} onClick={() => { dirty.current = true; setPreview(null); setShareholders(current => current.filter((_, n) => n !== index)); }}>Retirer</Button></div>)}<Button type="button" onClick={() => { dirty.current = true; setPreview(null); setShareholders(current => [...current, { name: "", shares: 0 }]); }}>Ajouter un associé</Button>{rounds.map((round, index) => <fieldset className="round-card" key={index}><legend>Tour {index + 1}</legend><div className="form-grid"><label>Nom du tour<input required value={round.name} onChange={e => editRound(index, "name", e.target.value)}/></label><label>Valorisation avant investissement (€)<input type="number" required min={1} value={round.pre_money} onChange={e => editRound(index, "pre_money", Number(e.target.value))}/></label><label>Montant levé (€)<input type="number" required min={1} value={round.investment} onChange={e => editRound(index, "investment", Number(e.target.value))}/></label><label>Pool salarié cible (%)<input type="number" required min={0} max={99.99} step="0.01" value={round.pool_percent} onChange={e => editRound(index, "pool_percent", Number(e.target.value))}/></label><label>Constitution du pool<select value={round.pool_timing} onChange={e => editRound(index, "pool_timing", e.target.value)}><option value="before">Avant le tour</option><option value="after">Après le tour</option></select></label></div><Button type="button" onClick={() => { dirty.current = true; setPreview(null); setRounds(current => current.filter((_, n) => n !== index)); }}>Retirer ce tour</Button></fieldset>)}<div className="button-group"><Button type="button" onClick={() => { dirty.current = true; setPreview(null); setRounds(current => [...current, { name: "Tour " + (current.length + 1), pre_money: 8000000, investment: 2000000, pool_percent: 0, pool_timing: "before" }]); }}>Ajouter un tour</Button><Button className="primary" disabled={p.busy}>Calculer et examiner la dilution</Button></div></form>{remote.data?.result && <CapitalResult result={remote.data.result}/>} {preview && <Review title="Aperçu de la capitalisation" preview={preview} busy={p.busy} close={() => setPreview(null)} apply={() => void p.mutate("/capitalization/apply", { approval_token: preview.approval_token }).then(() => { dirty.current = false; setPreview(null); }).catch(() => {})}/>}</Card>;
}

function Goals(p: Shared) {
  const questions = useData<{ questions: Question[] }>(p.case.id, "/questionnaire", p.refresh);
  const remote = useData<{ goals: { id: string; result?: { status?: string; target?: string; candidate?: { lever?: string; value?: string; residual?: string; proof?: { case_id?: string } }; evaluations?: number }; trials?: { case_id?: string; value?: string }[] }[] }>(p.case.id, "/goals", p.refresh);
  const results = <>{remote.data?.goals?.map(goal => <article className="round-card" key={goal.id}><h3>{statusLabel(goal.result?.status)}</h3><MetricTable metrics={{ "Cible": goal.result?.target, "Valeur obtenue": goal.result?.candidate?.value, "Valeur du levier": goal.result?.candidate?.lever, "Écart à la cible": goal.result?.candidate?.residual, "Évaluations effectuées": goal.result?.evaluations }}/>{goal.result?.candidate?.proof?.case_id && <Button onClick={() => p.onCase(goal.result!.candidate!.proof!.case_id!)}>Ouvrir le scénario proposé</Button>}<p className="note">Ce résultat n’a pas modifié le scénario de référence.</p></article>)}</>;
  const [waccNotice, setWaccNotice] = useState(""), [dcfNotice, setDcfNotice] = useState(""), [fiscalNotice, setFiscalNotice] = useState("");
  async function updateWaccCheck() {
    try { const result = await p.mutate<{ status?: string; operations?: unknown[] }>("/model/wacc-fingerprint", {}); if (result.status === "ALREADY_MIGRATED") setWaccNotice("Le contrôle WACC est déjà à jour. Votre brouillon est conservé."); else if (result.operations?.length) { setWaccNotice(""); p.onDraft(); } }
    catch { /* The existing draft stays available. */ }
  }
  async function adaptDcfCalendar() {
    setDcfNotice("");
    try { const result = await p.mutate<{ status?: string; operations?: unknown[] }>("/model/dcf-calendar", {}); if (result.status === "ALREADY_MIGRATED") setDcfNotice("La valorisation est déjà adaptée à l’horizon. Votre brouillon est conservé."); else if (result.operations?.length) p.onDraft(); }
    catch { /* A refused migration never clears the existing draft. */ }
  }
  async function adaptFiscalCalendar() {
    setFiscalNotice("");
    try { const result = await p.mutate<{ status?: string; operations?: unknown[] }>("/model/fiscal-calendar", {}); if (result.status === "ALREADY_MIGRATED") setFiscalNotice("La fiscalité et la trésorerie sont déjà adaptées à l’horizon. Votre brouillon est conservé."); else if (result.operations?.length) p.onDraft(); }
    catch { /* Refused preparation keeps the current draft and its evidence. */ }
  }
  const waccControls = <><details className="details-block"><summary>Contrôle de fraîcheur du WACC</summary><p className="note">La mise à jour corrige cinq formules de contrôle pour les horizons courts. Elle prépare une migration à examiner au brouillon et ne modifie pas le taux de valorisation.</p><Button disabled={p.busy} onClick={() => void updateWaccCheck()}>Mettre à jour le contrôle WACC</Button>{waccNotice && <p role="status">{waccNotice}</p>}</details><details className="details-block"><summary>Formules de valorisation et horizon</summary><p className="note">Cette migration adapte dix formules DCF pour exclure les années inactives du prévisionnel. Les informations manquantes des années actives restent à compléter. Examinez les changements au brouillon avant de les appliquer, puis recalculez. Terminez ou retirez votre brouillon courant avant de préparer cette migration.</p><Button disabled={p.busy} onClick={() => void adaptDcfCalendar()}>Adapter la valorisation à l’horizon</Button>{dcfNotice && <p role="status">{dcfNotice}</p>}</details><details className="details-block"><summary>Fiscalité, trésorerie et horizon</summary><p className="note">Cette migration prépare 56 formules : 55 agrégats annuels et l’indicateur de date de rupture de trésorerie du tableau de bord. Elle exclut les périodes non sélectionnées et conserve les erreurs des périodes retenues. Terminez ou retirez le brouillon courant, puis examinez ce lot séparément avant application. Confirmez les qualifications du nouveau modèle et recalculez ensuite.</p><Button disabled={p.busy} onClick={() => void adaptFiscalCalendar()}>Adapter fiscalité et trésorerie à l’horizon</Button>{fiscalNotice && <p role="status">{fiscalNotice}</p>}</details></>;
  const [field, setField] = useState(""), [metric, setMetric] = useState("cash_min"), [target, setTarget] = useState("0"), [lower, setLower] = useState("0"), [upper, setUpper] = useState("1000000"), [period, setPeriod] = useState("");
  return <Card title="Quel objectif d’activité atteindre ?" description="Choisissez une cible et un seul levier. Les autres hypothèses restent figées. Le résultat prépare un scénario à examiner."><form className="form-stack" onSubmit={e => { e.preventDefault(); void p.mutate("/goals", { field_id: questions.data?.questions?.find(q => questionKey(q) === field)?.field_id, sheet: questions.data?.questions?.find(q => questionKey(q) === field)?.sheet, cell: questions.data?.questions?.find(q => questionKey(q) === field)?.cell, metric, target: Number(target), lower: Number(lower), upper: Number(upper), period: metric === "valuation" ? null : period || null }).catch(() => {}); }}><div className="form-grid"><label>Indicateur cible<select value={metric} onChange={e => setMetric(e.target.value)}><option value="cash_min">Point bas de trésorerie</option><option value="net_income">Résultat net</option><option value="valuation">Valorisation</option></select></label><label>Valeur cible (€)<input type="number" step="any" required value={target} onChange={e => setTarget(e.target.value)}/></label><label>Levier à ajuster<select required value={field} onChange={e => setField(e.target.value)}><option value="">Choisir une hypothèse</option>{questions.data?.questions?.filter(q => numericQuestion(q) && !/wacc/i.test(q.field_id + q.label)).map(q => <option key={questionKey(q)} value={questionKey(q)}>{q.label || q.field_id} · {q.sheet}</option>)}</select></label><label>Période concernée<input type="month" disabled={metric === "valuation"} value={period} onChange={e => setPeriod(e.target.value)}/></label><label>Borne inférieure du levier<input type="number" step="any" required value={lower} onChange={e => setLower(e.target.value)}/></label><label>Borne supérieure du levier<input type="number" step="any" required value={upper} onChange={e => setUpper(e.target.value)}/></label></div><p className="note">{metric === "cash_min" ? "Point bas mesuré du début du prévisionnel au mois choisi, ou sur tout le calendrier si aucun mois ne figure." : metric === "net_income" ? "Résultat de l’année contenant le mois choisi ; sans période, le résultat annuel du modèle est utilisé." : "Valorisation sur l’horizon du modèle et à sa date de référence. La période mensuelle ne s’applique pas."}</p><Button disabled={p.busy || !field || Number(lower) >= Number(upper)}>Rechercher un scénario atteignant la cible</Button></form>{results}{waccControls}</Card>;
}

function Sensitivities(p: Shared) {
  const questions = useData<{ questions: Question[] }>(p.case.id, "/questionnaire", p.refresh);
  const remote = useData<{ campaigns: { id: string; name?: string; status?: string; points?: { values: unknown; case_id?: string; metrics?: Record<string, unknown> }[] }[] }>(p.case.id, "/sensitivities", p.refresh);
  const [axes, setAxes] = useState([{ key: "", values: "" }]);
  const parsed = axes.map(axis => ({ question: questions.data?.questions?.find(q => questionKey(q) === axis.key), values: axis.values.split(";").map(value => parseValue(value, "fr")) }));
  const valid = parsed.every(axis => axis.question && axis.values.length >= 2 && axis.values.length <= 20 && axis.values.every(v => typeof v === "number")) && parsed.reduce((n, axis) => n * axis.values.length, 1) <= 25;
  return <Card title="Analyses de sensibilité" description="Faites varier une ou deux hypothèses sur des copies isolées. Chaque point conserve les valeurs testées et ses résultats calculés."><FetchError message={remote.error} retry={remote.retry}/><form className="form-stack" onSubmit={e => { e.preventDefault(); void p.mutate("/sensitivities", { axes: parsed.map(axis => ({ field_id: axis.question?.field_id, sheet: axis.question?.sheet, cell: axis.question?.cell, values: axis.values })) }).catch(() => {}); }}>{axes.map((axis, index) => <div className="form-grid" key={index}><label>Hypothèse de l’axe {index + 1}<select required value={axis.key} onChange={e => setAxes(current => current.map((a, n) => n === index ? { ...a, key: e.target.value } : a))}><option value="">Choisir une hypothèse</option>{questions.data?.questions?.filter(numericQuestion).map(q => <option key={questionKey(q)} value={questionKey(q)}>{q.label || q.field_id} · {q.sheet} · {q.cell}</option>)}</select></label><label>Valeurs de l’axe {index + 1}, séparées par ;<input required value={axis.values} onChange={e => setAxes(current => current.map((a, n) => n === index ? { ...a, values: e.target.value } : a))} placeholder="80 ; 100 ; 120"/></label></div>)}<p className="note">Nombres au format français. De 2 à 20 valeurs par axe ; 25 combinaisons au maximum par campagne.</p><div className="button-group"><Button type="button" onClick={() => setAxes(current => current.length === 1 ? [...current, { key: "", values: "" }] : current.slice(0, 1))}>{axes.length === 1 ? "Ajouter un second axe" : "Garder un seul axe"}</Button><Button disabled={p.busy || !valid} className="primary">Lancer la campagne</Button></div></form>{remote.data?.campaigns?.map(campaign => <details className="details-block" key={campaign.id}><summary>{campaign.name || "Campagne de sensibilité"} · {statusLabel(campaign.status)} · {campaign.points?.length || 0} points</summary>{campaign.points?.map((point, index) => <article className="sensitivity-point" key={index}><h3>Hypothèses : {valueText(point.values)}</h3><MetricTable metrics={point.metrics}/>{point.case_id && <Button onClick={() => p.onCase(point.case_id!)}>Ouvrir ce point</Button>}</article>)}</details>)}</Card>;
}

function Actuals(p: Shared) {
  const remote = useData<{ rows: ActualRow[]; cutoff?: string; comparisons?: Record<string, unknown>[]; diagnostics?: unknown; history?: Record<string, unknown>[]; forecast_status?: string; annual_balance?: { period: string; assets: number | null; liabilities: number | null; equity: number | null; net_income: number | null; balance_check: number | null; model_balance_check: number | null }[]; forecast_series?: { id: string; label?: string; categories: string[]; values: (number | null)[] }[]; metrics_catalog?: { id: string; label: string; kind: string; unit: string }[] }>(p.case.id, "/actuals", p.refresh);
  const [rows, setRows] = useState<ActualRow[]>([{ period: "", metric: "", kind: "flow", value: "", unit: "EUR" }]), [cutoff, setCutoff] = useState("");
  const [file, setFile] = useState<File | null>(null), [columns, setColumns] = useState<string[]>([]), [mapping, setMapping] = useState<Record<string, string>>({}), [locale, setLocale] = useState<NumericLocale>("fr"), [encoding, setEncoding] = useState("utf-8"), [preview, setPreview] = useState<Preview | null>(null), [uploadError, setUploadError] = useState(""), [uploading, setUploading] = useState(false);
  const [metricValues, setMetricValues] = useState<string[]>([]), [metricMapping, setMetricMapping] = useState<Record<string, string>>({});
  const [ledgerPage, setLedgerPage] = useState(0);
  const ledgerOffset = Math.min(ledgerPage, Math.max(0, Math.ceil((remote.data?.rows?.length || 0) / 200) - 1)) * 200;
  const unmapped = metricValues.filter(value => !remote.data?.metrics_catalog?.some(metric => metric.id === value));
  const postMapping = !!unmapped.length && <fieldset className="round-card"><legend>Associer vos postes au prévisionnel</legend><p className="note">Choisissez le poste métier correspondant à chaque libellé de votre fichier. Le flux, solde ou volume est déterminé par ce choix si vous ne mappez pas une colonne de nature.</p><div className="form-grid">{unmapped.map(value => <label key={value}>{value}<select aria-label={"Correspondance du poste : " + value} value={metricMapping[value] || ""} onChange={e => { setMetricMapping(current => ({ ...current, [value]: e.target.value })); setPreview(null); }}><option value="">Choisir le poste métier</option>{remote.data?.metrics_catalog?.map(metric => <option key={metric.id} value={metric.id}>{metric.label}</option>)}</select></label>)}</div></fieldset>;
  async function importFile() {
    if (!file) return; setUploading(true); setUploadError("");
    const body = new FormData(); body.append("file", file); body.append("mapping", JSON.stringify(mapping)); body.append("metric_mapping", JSON.stringify(metricMapping)); body.append("numeric_locale", locale); body.append("encoding", encoding); body.append("cutoff", cutoff); body.append("expected_revision", String(p.case.revision ?? 0));
    try { const response = await intentUpload<{ columns?: string[]; rows?: ActualRow[]; metric_values?: string[]; needs_metric_mapping?: boolean; preview?: Preview }>(p.case.id, "/actuals/import", body); if (response.columns) setColumns(response.columns); if (response.metric_values) setMetricValues(response.metric_values); if (response.preview) setPreview(response.preview); }
    catch (e) { setUploadError(errorText(e)); } finally { setUploading(false); }
  }
  async function manual(e: FormEvent) { e.preventDefault(); try { const response = await p.mutate<Preview & { preview?: Preview }>("/actuals", { rows: rows.map(row => ({ ...row, value: typeof row.value === "string" ? parseValue(row.value, locale) : row.value })), cutoff, numeric_locale: locale }); setPreview(response.preview || response); } catch { /* Preserve manual data. */ } }
  const annual = !!remote.data?.annual_balance?.length && <details className="details-block"><summary>Bilan et résultat annuels actualisés</summary><p className="note">Les montants restent à compléter tant que le budget, les sources, les contrôles et le recalcul du raccord ne sont pas validés. Un contrôle équilibré vaut zéro.</p><div className="draft-table-wrap"><table className="plain-table" aria-label="Bilan et résultat annuels actualisés"><thead><tr><th>Année</th><th>Actif (€)</th><th>Passifs hors capitaux propres (€)</th><th>Capitaux propres (€)</th><th>Résultat net (€)</th><th>Écart bilan actualisé (€)</th><th>Écart bilan modèle (€)</th></tr></thead><tbody>{remote.data?.annual_balance?.map(year => <tr key={year.period}><td>{year.period}</td><td>{valueText(year.assets)}</td><td>{valueText(year.liabilities)}</td><td>{valueText(year.equity)}</td><td>{valueText(year.net_income)}</td><td>{valueText(year.balance_check)}</td><td>{valueText(year.model_balance_check)}</td></tr>)}</tbody></table></div></details>;
  const forecast = <Card title="Prévision actualisée"><BridgeForm case={p.case} sources={p.sources} refresh={p.refresh} busy={p.busy} enabled={!!remote.data?.rows?.length} onSource={p.onSource} onDraft={p.onDraft} submit={body => p.mutate("/actuals/reforecast", body)}/><p className="badge warning">{statusLabel(remote.data?.forecast_status)}</p><p className="note">Les mois passés utilisent les données validées. Les mois suivants suivent les hypothèses courantes ; les contrôles de raccord doivent être satisfaits avant leur utilisation.</p>{remote.data?.forecast_series?.map(series => <details className="details-block" key={series.id}><summary>{series.label || remote.data?.metrics_catalog?.find(m => m.id === series.id)?.label || series.id}</summary><div className="draft-table-wrap"><table className="plain-table"><thead><tr><th>Mois</th><th>Origine</th><th>Valeur</th></tr></thead><tbody>{series.categories.map((period, index) => <tr key={period}><td>{period}</td><td>{period <= (remote.data?.cutoff || "").slice(0, 7) ? "Réalisé" : "Prévision"}</td><td>{valueText(series.values[index])}</td></tr>)}</tbody></table></div></details>)}{annual}</Card>;
  return <><Card title="Suivi mensuel du réalisé" description="Le budget initial, le réalisé et la prévision actualisée sont conservés séparément. Choisissez un arrêté au dernier jour du mois. Les données absentes restent à compléter."><FetchError message={remote.error} retry={remote.retry}/><div className="form-grid"><label>Date d’arrêté<input aria-label="Date d’arrêté du réalisé" type="date" required value={cutoff} onChange={e => { setCutoff(e.target.value); setPreview(null); }}/></label><label>Format des nombres<select value={locale} onChange={e => { setLocale(e.target.value as NumericLocale); setPreview(null); }}><option value="fr">Français : 1 234,56</option><option value="en">Anglais : 1,234.56</option></select></label></div><p className="note">Dernier arrêté validé : {remote.data?.cutoff || "Aucun réalisé validé"}</p><Diagnostics value={remote.data?.diagnostics}/></Card><Card title="Importer un tableau Excel ou CSV"><label>Encodage du CSV<select aria-label="Encodage du CSV" value={encoding} onChange={e => { setEncoding(e.target.value); setColumns([]); setMapping({}); setMetricValues([]); setMetricMapping({}); setPreview(null); setUploadError(""); }}><option value="utf-8">UTF-8 (avec ou sans BOM)</option><option value="cp1252">Windows-1252</option></select></label><p className="note">Ce choix s’applique aux fichiers CSV. Confirmez les accents des en-têtes après lecture ; aucun encodage n’est deviné.</p><label className="drop-zone">Fichier du réalisé<input aria-label="Fichier du réalisé" type="file" accept=".xlsx,.xlsm,.csv" onChange={e => { setFile(e.target.files?.[0] || null); setColumns([]); setMapping({}); setMetricValues([]); setMetricMapping({}); setPreview(null); }}/></label>{columns.length > 0 && <div className="form-grid">{[{ key: "period", label: "Période" }, { key: "metric", label: "Poste métier" }, { key: "value", label: "Valeur" }, { key: "kind", label: "Flux, solde ou volume" }, { key: "unit", label: "Unité" }].map(column => <label key={column.key}>{column.label}<select value={mapping[column.key] || ""} onChange={e => { setMapping(current => ({ ...current, [column.key]: e.target.value })); setPreview(null); }}><option value="">Choisir une colonne</option>{columns.map(name => <option key={name}>{name}</option>)}</select></label>)}</div>}{postMapping}{uploadError && <div className="inline-error" role="alert">{uploadError}</div>}<Button disabled={!file || uploading || !cutoff || unmapped.some(value => !metricMapping[value])} onClick={() => void importFile()}>{uploading ? "Lecture…" : columns.length ? "Prévisualiser les lignes importées" : "Lire les colonnes du fichier"}</Button></Card><Card title="Saisir des données mensuelles"><form className="form-stack" onSubmit={manual}>{rows.map((row, index) => <fieldset className="round-card" key={index}><legend>Ligne {index + 1}</legend><div className="form-grid">{[{ key: "period", label: "Mois", type: "month" }, { key: "metric", label: "Poste métier", type: "text" }, { key: "value", label: "Valeur", type: "text" }, { key: "unit", label: "Unité", type: "text" }].map(field => <label key={field.key}>{field.label}{field.key === "metric" ? <select required aria-label={"Poste métier ligne " + (index + 1)} value={row.metric} onChange={e => { const metric = remote.data?.metrics_catalog?.find(m => m.id === e.target.value); setPreview(null); setRows(current => current.map((r, n) => n === index ? { ...r, metric: e.target.value, kind: metric?.kind || r.kind, unit: metric?.unit || r.unit } : r)); }}><option value="">Choisir un poste</option>{remote.data?.metrics_catalog?.map(metric => <option key={metric.id} value={metric.id}>{metric.label}</option>)}</select> : <input required type={field.type} value={displayValue(row[field.key as keyof ActualRow])} onChange={e => { setPreview(null); setRows(current => current.map((r, n) => n === index ? { ...r, [field.key]: e.target.value } : r)); }}/>}</label>)}<label>Nature<select value={row.kind} onChange={e => { setPreview(null); setRows(current => current.map((r, n) => n === index ? { ...r, kind: e.target.value } : r)); }}><option value="flow">Flux du mois</option><option value="balance">Solde à fin de mois</option><option value="volume">Volume</option></select></label></div><Button type="button" disabled={rows.length < 2} onClick={() => setRows(current => current.filter((_, n) => n !== index))}>Retirer la ligne</Button></fieldset>)}<div className="button-group"><Button type="button" onClick={() => setRows(current => [...current, { period: "", metric: "", kind: "flow", value: "", unit: "EUR" }])}>Ajouter une ligne</Button><Button className="primary" disabled={p.busy || !cutoff}>Vérifier le réalisé saisi</Button></div></form></Card><Card title="Données validées et écarts"><PageNavigation count={remote.data?.rows?.length || 0} page={ledgerPage} onPage={setLedgerPage} label="données validées"/><div className="draft-table-wrap"><table className="plain-table"><thead><tr><th>Mois</th><th>Poste</th><th>Nature</th><th>Valeur</th></tr></thead><tbody>{remote.data?.rows?.slice(ledgerOffset, ledgerOffset + 200).map((row, index) => <tr key={index}><td>{row.period}</td><td>{row.metric}</td><td>{row.kind === "balance" ? "Solde" : row.kind === "volume" ? "Volume" : "Flux"}</td><td>{valueText(row.value)} {row.unit}</td></tr>)}</tbody></table></div>{remote.data?.comparisons?.map((comparison, index) => <MetricTable key={index} metrics={comparison}/>)}<Diagnostics value={remote.data?.history}/></Card>{forecast}<AccountingHelp caseId={p.case.id}/>{preview && <Review title="Aperçu du réalisé" preview={preview} busy={p.busy} close={() => setPreview(null)} apply={() => void p.mutate("/actuals/apply", { approval_token: preview.approval_token }).then(() => { setPreview(null); setRows([{ period: "", metric: "", kind: "flow", value: "", unit: "EUR" }]); }).catch(() => {})}/>}</>;
}

function AccountingHelp({ caseId }: { caseId: string }) {
  const [account, setAccount] = useState(""), [balance, setBalance] = useState("0"), [year, setYear] = useState(new Date().getFullYear());
  const [busy, setBusy] = useState(false), [error, setError] = useState(""), [result, setResult] = useState<{ matched_prefix?: string; label?: string; post?: { code?: string; label?: string; libelle?: string }; status?: string; warnings?: unknown; note?: string; reference_version?: string } | null>(null);
  async function suggest(event: FormEvent) {
    event.preventDefault(); setBusy(true); setError(""); setResult(null);
    const parsed = parseValue(balance, "fr");
    if (typeof parsed !== "number") { setError("Saisissez un solde numérique au format français."); setBusy(false); return; }
    try { setResult(await api(casePath(caseId) + "/accounting/mapping?" + new URLSearchParams({ account, balance: String(parsed), year: String(year) }))); }
    catch (e) { setError(errorText(e)); } finally { setBusy(false); }
  }
  return <Card title="Aide à la correspondance comptable" description="Consultez le classement proposé par votre référentiel de comptes. La correspondance reste à confirmer avant son utilisation."><form className="form-stack" onSubmit={suggest}><div className="form-grid"><label>Compte PCG<input required minLength={2} value={account} onChange={e => { setAccount(e.target.value); setResult(null); }} placeholder="Exemple : 411000"/></label><label>Solde signé (débit +, crédit −)<input required value={balance} onChange={e => { setBalance(e.target.value); setResult(null); }}/></label><label>Exercice comptable<input required type="number" min={1900} max={2200} value={year} onChange={e => { setYear(Number(e.target.value)); setResult(null); }}/></label></div><Button disabled={busy || !account.trim()}>{busy ? "Recherche…" : "Consulter la correspondance"}</Button></form>{error && <div className="inline-error" role="alert">{error}</div>}{result && <><span className={"badge " + (result.status === "A_REVOIR" ? "warning" : "")}>{statusLabel(result.status)}</span><MetricTable metrics={{ "Compte de référence": result.matched_prefix, "Libellé du compte": result.label, "Poste proposé": result.post ? `${result.post.code || ""} · ${result.post.label || result.post.libelle || ""}` : null }}/><Diagnostics value={result.warnings}/><p className="note">{result.note} Référentiel : {result.reference_version || "version du dossier"}. Aucune écriture n’a été appliquée.</p></>}</Card>;
}

function Reports(p: Shared) {
  const remote = useData<{ reports: Report[] }>(p.case.id, "/reports", p.refresh);
  const overview = useData<{ storage?: { used_bytes?: number; free_bytes?: number } }>(p.case.id, "/workshop", p.refresh);
  const [file, setFile] = useState<File | null>(null), [uploading, setUploading] = useState(false), [error, setError] = useState("");
  const storage = <Card title="Espace du dossier"><p className="note">Versions, sources et preuves conservées.</p><MetricTable metrics={{ "Espace utilisé (Mo)": overview.data?.storage?.used_bytes == null ? null : overview.data.storage.used_bytes / 1048576, "Espace disponible (Go)": overview.data?.storage?.free_bytes == null ? null : overview.data.storage.free_bytes / 1073741824 }}/></Card>;
  async function roundtrip() { if (!file) return; setUploading(true); setError(""); const body = new FormData(); body.append("file", file); body.append("expected_revision", String(p.case.revision ?? 0)); try { await intentUpload(p.case.id, "/roundtrip", body); await p.onRefresh(); p.onDraft(); } catch (e) { setError(errorText(e)); } finally { setUploading(false); } }
  return <><Card title="Excel et rapports du dossier" description="Chaque jeu de livrables est lié à un même instantané calculé. Les chiffres, périodes, sources et hypothèses sont conservés ensemble."><FetchError message={remote.error} retry={remote.retry}/><p className="note">Révision courante {p.case.revision ?? 0} · {statusLabel(p.case.calculation_status)}</p><Button className="primary" disabled={p.busy} onClick={() => void p.mutate("/reports", { formats: ["xlsm", "pdf", "docx", "pptx"] }).catch(() => {})}>Préparer les quatre livrables</Button><div className="document-list">{remote.data?.reports?.map(report => <article key={report.id}><div><h3>Livrables · révision {report.revision ?? "—"}</h3><p className="note">{statusLabel(report.status)} {report.created_at ? " · " + new Date(report.created_at).toLocaleString("fr-FR") : ""}</p></div><div className="button-group">{(!report.status || ["READY", "SUCCEEDED", "COMPLETE", "GENERATED", "CONFIRME"].includes(report.status) ? (report.formats || ["xlsm", "pdf", "docx", "pptx"]) : []).map(format => <a className="button" key={format} href={"/api" + casePath(p.case.id) + "/reports/" + encodeURIComponent(report.id) + "/" + format} download>{({ xlsm: "Excel", pdf: "PDF", docx: "Word", pptx: "PowerPoint" } as Record<string, string>)[format] || format}</a>)}</div>{(!report.status || ["READY", "SUCCEEDED", "COMPLETE", "GENERATED", "CONFIRME"].includes(report.status)) && <a className="text-button" href={"/api" + casePath(p.case.id) + "/reports/" + encodeURIComponent(report.id) + "/snapshot"} target="_blank" rel="noreferrer">Détail des chiffres (JSON)</a>}<Diagnostics value={report.warnings}/></article>)}</div>{!remote.data?.reports?.length && <p className="note">Aucun jeu de livrables préparé pour le moment.</p>}</Card>{storage}<Card title="Reprendre les corrections d’un Excel exporté" description="Choisissez un Excel téléchargé depuis un jeu de livrables ci-dessus. Seules les entrées reconnues sont proposées au brouillon. Les modifications de formules ou de structure font l’objet d’un diagnostic."><label className="drop-zone">Classeur exporté puis modifié<input aria-label="Classeur exporté puis modifié" type="file" accept=".xlsm,.xlsx" onChange={e => setFile(e.target.files?.[0] || null)}/></label>{error && <div className="inline-error" role="alert">{error}</div>}<Button disabled={!file || uploading} onClick={() => void roundtrip()}>{uploading ? "Comparaison…" : "Comparer et préparer les corrections"}</Button></Card></>;
}
